export const ALIEN_CREATURES = [{"id": 462, "name": "Blinkbot", "title": "The Spark Scout", "rarity": "Common", "types": ["Electric"], "weak": ["Earth", "Rock"], "fam": "C-51", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Bulb Flash", "atkType": "Electric", "alt": {"name": "Wheel Zap", "type": "Electric", "mult": 1.22}, "ux": {"main": {"fx": "daze", "ch": 0.2, "pct": 0.1}, "alt": {"fx": "bonus", "ch": 0.15, "pct": 0.2}, "pass": {"fx": "critBoost", "pct": 0.1, "name": "Bright Idea!"}}, "hp": 42, "df": 14, "dmg": 16, "ghp": 3.5, "gdf": 1.2, "gdmg": 1.5, "img": "assets/planet/alien-landing-c-360.webp", "event": "planet", "planet": "landing", "tier": "c", "lore": "Blinkbot is a tiny, cheerful creature frequently discovered near abandoned laboratories, old electrical towers, and mysterious pieces of machinery. Although it resembles a miniature robot, researchers believe Blinkbot may actually be an alien life-form whose body naturally produces metallic armor. Its most recognizable feature is the glowing light bulb on top of its head, which changes brightness depending on its emotions. When Blinkbot is happy, the bulb shines brightly. When frightened, it flickers rapidly. When confused, it occasionally goes out entirely! Rather than walking, Blinkbot travels using a single electrically powered hover wheel, allowing it to zip across smooth surfaces at surprising speeds. Blinkbot is fascinated by anything that lights up, especially glowing crystals, lanterns, and colorful decorations. Despite its small size, it can generate powerful electrical sparks when excited. Researchers believe Blinkbot's light-bulb antenna helps it communicate with other members of its species. Fun fact: Blinkbot occasionally gets so excited by a new discovery that its antenna lights up too brightly, temporarily dazzling itself!", "moves": [{"name": "Bulb Flash", "type": "Electric", "dmg": 18, "effect": "20% chance to reduce the enemy's next attack damage by 10%"}, {"name": "Wheel Zap", "type": "Electric", "dmg": 22, "effect": "15% chance to deal 20% bonus damage"}], "ability": {"name": "Bright Idea!", "text": "Whenever Blinkbot lands a critical hit, its antenna flashes brilliantly. Its next attack deals 10% additional damage."}, "role": "Quick Electric attacker / disruptive support"}, {"id": 463, "name": "Zibbit", "title": "The Spark Tinkerer", "rarity": "Rare", "types": ["Steel", "Electric"], "weak": ["Fire", "Earth", "Rock"], "fam": "R-26", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Wrench Whack", "atkType": "Steel", "alt": {"name": "Spark Circuit", "type": "Electric", "mult": 1.08}, "ux": {"main": {"fx": "defdown", "ch": 0.2, "pct": 0.15}, "alt": {"fx": "daze", "ch": 0.2, "pct": 0.15}, "pass": {"fx": "halfHeal", "pct": 0.1, "name": "Quick Fix"}}, "hp": 65, "df": 26, "dmg": 24, "ghp": 4.5, "gdf": 1.8, "gdmg": 1.8, "img": "assets/planet/alien-landing-360.webp", "event": "planet", "planet": "landing", "tier": "r", "lore": "Hidden inside abandoned workshops and forgotten factories lives a curious little creature known as Zibbit. With enormous mechanical rabbit ears and a tool belt filled with miniature gadgets, Zibbit spends nearly every waking moment building, repairing, or experimenting with machinery. Although much of its body is covered in metallic plating, researchers believe Zibbit is a naturally occurring creature rather than an artificial invention. Its enormous ears can detect even the smallest electrical signals, allowing it to locate malfunctioning machines from remarkable distances. Zibbit is especially fond of broken toys, discarded gadgets, and mysterious mechanical objects. It often collects these treasures and transforms them into entirely new inventions. Despite its extraordinary talent, Zibbit's experiments do not always go according to plan. Some of its inventions explode into harmless showers of sparks, while others develop unexpected abilities. Researchers believe Zibbit becomes happiest when it successfully repairs something that another creature has given up on. Some stories claim that lost travelers have awakened to discover their broken equipment mysteriously repaired overnight, with tiny rabbit-shaped footprints scattered nearby. Fun fact: Zibbit frequently forgets which pocket contains its wrench, even though it uses the same pocket every day!", "moves": [{"name": "Wrench Whack", "type": "Steel", "dmg": 26, "effect": "20% chance to reduce enemy Defense by 15%"}, {"name": "Spark Circuit", "type": "Electric", "dmg": 28, "effect": "20% chance to reduce enemy next attack damage by 15%"}], "ability": {"name": "Quick Fix", "text": "Zibbit can use its tools to make emergency repairs to its own metallic body. Passive: the first time Zibbit falls below 50% HP, it restores 10% of its maximum HP."}, "role": "Defensive support / electrical disruptor"}, {"id": 464, "name": "Quasarpup", "title": "The Cosmic Rocket Hound", "rarity": "Super Rare", "types": ["Normal", "Steel"], "weak": ["Fire", "Electric", "Arcane"], "fam": "S-38", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Rocket Zoomies", "atkType": "Normal", "alt": {"name": "Meteor Paw", "type": "Steel", "mult": 1.07}, "ux": {"main": {"fx": "evade", "ch": 0.2}, "alt": {"fx": "bonus", "ch": 0.2, "pct": 0.25}, "pass": {"fx": "halfShield", "pct": 0.25, "name": "Starbound Spirit"}}, "hp": 80, "df": 29, "dmg": 28, "ghp": 5, "gdf": 2, "gdmg": 2, "img": "assets/planet/alien-landing-s-360.webp", "event": "planet", "planet": "landing", "tier": "s", "lore": "Far beyond the highest mountain peaks, where the night sky stretches into an endless ocean of stars, lives a remarkable creature known as Quasarpup. Legends claim Quasarpup first appeared when a lonely shooting star fell to Earth and transformed into a tiny, fluffy puppy. Its extraordinary rocket boots allow it to leap incredible distances, soar through the air, and explore places that ordinary creatures could never reach. Despite its futuristic equipment, Quasarpup is a naturally playful and affectionate creature. It loves chasing falling stars, investigating mysterious objects, and making friends with creatures it encounters during its adventures. The glowing star charm on its collar is said to contain a tiny fragment of the star from which it was born. Researchers believe the charm acts as a magical compass, guiding Quasarpup home whenever it becomes lost. Although Quasarpup is brave and adventurous, it is also incredibly loyal. It has been known to travel enormous distances to reunite lost creatures with their families. Some legends claim that whenever a shooting star suddenly changes direction, it is actually Quasarpup racing across the night sky. Fun fact: Quasarpup loves playing fetch, but sometimes forgets to turn off its rocket boots and accidentally launches itself several hundred feet past the ball!", "moves": [{"name": "Rocket Zoomies", "type": "Normal", "dmg": 30, "effect": "20% chance to dodge the next attack"}, {"name": "Meteor Paw", "type": "Steel", "dmg": 32, "effect": "20% chance to deal 25% bonus damage"}], "ability": {"name": "Starbound Spirit", "text": "Quasarpup's adventurous spirit makes it incredibly difficult to discourage. Passive: the first time Quasarpup falls below 50% HP, its rocket boots activate an emergency boost, reducing damage from the next incoming attack by 25%."}, "role": "Fast physical attacker / evasive specialist"}, {"id": 465, "name": "Pollywiggle", "title": "The Puddle Hopper", "rarity": "Common", "types": ["Nature", "Water"], "weak": ["Fire", "Ice", "Poison", "Electric", "Nature"], "fam": "C-52", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Puddle Pop", "atkType": "Water", "alt": {"name": "Sprout Splash", "type": "Nature", "mult": 0.9}, "ux": {"main": {"fx": "evade", "ch": 0.2}, "alt": {"fx": "heal", "ch": 0.2, "pct": 0.1}, "pass": {"fx": "halfShield", "pct": 0.2, "name": "Leapfrog Luck"}}, "hp": 44, "df": 13, "dmg": 15, "ghp": 3.5, "gdf": 1.2, "gdmg": 1.5, "img": "assets/planet/alien-jungle-c-360.webp", "event": "planet", "planet": "jungle", "tier": "c", "lore": "Hidden among the glowing ponds and mysterious wetlands of the world lives a curious little creature known as Pollywiggle. Although it resembles an ordinary tadpole, researchers believe Pollywiggle may have originated from a distant world where entire forests float upon enormous oceans. Its translucent body contains a mysterious glowing seed that produces both water and Nature energy. Pollywiggle uses its enormous spring-shaped tail to launch itself between puddles, allowing it to travel across vast distances without ever touching dry ground. Whenever it lands in water, tiny flowers briefly bloom around the edges of the splash. Despite its unusual appearance, Pollywiggle is extremely friendly and enjoys following other creatures through forests and wetlands. It is particularly fascinated by reflections, often attempting to play with its own image in the water. Researchers have discovered that Pollywiggle's glowing antennae allow it to communicate with nearby plants, encouraging flowers and water lilies to bloom. Some legends claim that a group of Pollywiggles bouncing together can transform an ordinary muddy puddle into a beautiful glowing garden overnight. Fun fact: Pollywiggle occasionally mistakes raindrops for tiny puddles and tries to jump into them before they reach the ground!", "moves": [{"name": "Puddle Pop", "type": "Water", "dmg": 20, "effect": "20% chance to dodge the next attack"}, {"name": "Sprout Splash", "type": "Nature", "dmg": 18, "effect": "20% chance to restore 10% maximum HP"}], "ability": {"name": "Leapfrog Luck", "text": "Pollywiggle's incredible bouncing ability makes it difficult to hit. Passive: the first time Pollywiggle falls below 50% HP, it springs into the air, reducing damage from the next incoming attack by 20%."}, "role": "Evasive attacker / minor healing support"}, {"id": 466, "name": "Glimmersprout", "title": "The Little Lantern", "rarity": "Rare", "types": ["Nature", "Light"], "weak": ["Fire", "Ice", "Poison", "Dark", "Ghost"], "fam": "R-27", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Firefly Flash", "atkType": "Light", "alt": {"name": "Sprout Shine", "type": "Nature", "mult": 0.89}, "ux": {"main": {"fx": "daze", "ch": 0.2, "pct": 0.15}, "alt": {"fx": "heal", "ch": 0.2, "pct": 0.1}, "pass": {"fx": "halfShield", "pct": 0.2, "name": "Guiding Glow"}}, "hp": 43, "df": 15, "dmg": 14, "ghp": 3.5, "gdf": 1.3, "gdmg": 1.4, "img": "assets/planet/alien-jungle-360.webp", "event": "planet", "planet": "jungle", "tier": "r", "lore": "Deep within enchanted forests, where moonlight filters through enormous leaves and tiny flowers glow beneath the trees, lives a curious little creature known as Glimmersprout. Although it resembles a tiny walking seedling, researchers believe Glimmersprout originated from a distant world where plants communicate using flashes of light. Its most recognizable feature is a glowing antenna that resembles the luminous abdomen of a firefly. This antenna produces a warm golden light that helps Glimmersprout navigate dark forests and communicate with other members of its species. Glimmersprout is naturally gentle and prefers helping other creatures rather than fighting. It frequently guides lost travelers through forests, illuminating safe paths with its glowing antenna. Researchers have observed that flowers exposed to Glimmersprout's light often bloom earlier than expected. Some legends claim that Glimmersprout's glow can reveal hidden paths that remain invisible during daylight. Although Glimmersprout is small and timid, it becomes surprisingly brave whenever another creature needs help. Fun fact: Glimmersprout sometimes mistakes ordinary fireflies for other Glimmersprouts and spends hours trying to communicate with them by flashing its antenna!", "moves": [{"name": "Firefly Flash", "type": "Light", "dmg": 19, "effect": "20% chance to reduce the enemy's next attack damage by 15%"}, {"name": "Sprout Shine", "type": "Nature", "dmg": 17, "effect": "20% chance to restore 10% maximum HP"}], "ability": {"name": "Guiding Glow", "text": "Glimmersprout's gentle light becomes stronger whenever it needs to protect itself. Passive: the first time Glimmersprout falls below 50% HP, its antenna flashes brightly, reducing damage from the next incoming attack by 20%."}, "role": "Healing support / defensive utility"}, {"id": 467, "name": "Orchidra", "title": "The Mystic Bloom", "rarity": "Super Rare", "types": ["Nature", "Arcane"], "weak": ["Fire", "Ice", "Poison", "Dark", "Steel"], "fam": "S-39", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Petal Hex", "atkType": "Arcane", "alt": {"name": "Orchid Whirl", "type": "Nature", "mult": 0.87}, "ux": {"main": {"fx": "defdown", "ch": 0.2, "pct": 0.15}, "alt": {"fx": "heal", "ch": 0.2, "pct": 0.1}, "pass": {"fx": "halfShield", "pct": 0.2, "name": "Third Eye Insight"}}, "hp": 40, "df": 13, "dmg": 18, "ghp": 3.3, "gdf": 1.2, "gdmg": 1.7, "img": "assets/planet/alien-jungle-s-360.webp", "event": "planet", "planet": "jungle", "tier": "s", "lore": "Hidden within enchanted gardens and mysterious forests lives a tiny alien creature known as Orchidra. Its beautiful orchid-petal wings allow it to float silently through the air, while its unusual third eye detects magical energy invisible to most creatures. Researchers believe Orchidra originated from a distant world where flowers grow in the sky and plants communicate through magical light. Despite its mysterious appearance, Orchidra is friendly and curious. It frequently approaches travelers to inspect their belongings, especially anything that glows or sparkles. Its delicate petals contain powerful Nature and Arcane energy, allowing it to encourage flowers to bloom and create small magical illusions. Orchidra's third eye is particularly sensitive to hidden magic. It has been known to discover enchanted objects buried deep beneath the ground. Some legends claim that when a group of Orchidras gathers beneath a full moon, their wings create a beautiful floating garden of glowing orchids. Although Orchidra prefers peaceful environments, it can defend itself by releasing swirling petals infused with magical energy. Fun fact: Orchidra occasionally uses its third eye to search for hidden treats, but it becomes very embarrassed when someone catches it peeking inside their bag!", "moves": [{"name": "Petal Hex", "type": "Arcane", "dmg": 23, "effect": "20% chance to reduce enemy Defense by 15%"}, {"name": "Orchid Whirl", "type": "Nature", "dmg": 20, "effect": "20% chance to restore 10% maximum HP"}], "ability": {"name": "Third Eye Insight", "text": "Orchidra's magical third eye allows it to anticipate incoming attacks. Passive: the first time Orchidra falls below 50% HP, it reduces damage from the next incoming attack by 20%."}, "role": "Magical attacker / enemy debuffer"}, {"id": 468, "name": "Clinkle", "title": "The Little Crystal Spark", "rarity": "Common", "types": ["Crystal"], "weak": ["Steel", "Earth"], "fam": "C-53", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Shard Flick", "atkType": "Crystal", "alt": {"name": "Prism Blink", "type": "Crystal", "mult": 0.9}, "ux": {"main": {"fx": "bonus", "ch": 0.2, "pct": 0.2}, "alt": {"fx": "shield", "ch": 0.2, "pct": 0.15}, "pass": {"fx": "halfShield", "pct": 0.2, "name": "Crystal Clarity"}}, "hp": 41, "df": 18, "dmg": 15, "ghp": 3.4, "gdf": 1.5, "gdmg": 1.4, "img": "assets/planet/alien-caves-c-360.webp", "event": "planet", "planet": "caves", "tier": "c", "lore": "Deep within glittering caves and ancient crystal formations lives a tiny alien creature known as Clinkle. Although it resembles an ordinary gemstone, Clinkle is a living creature with a single enormous eye and a surprisingly playful personality. Researchers believe Clinkle was born when mysterious energy from a distant star became trapped inside a growing crystal. Its translucent body contains a glowing core that produces beautiful rainbow reflections whenever sunlight passes through it. Clinkle uses its enormous eye to detect tiny movements and changes in light, allowing it to navigate even the darkest caverns. Despite its small size, Clinkle is extremely curious and loves collecting shiny stones, polished metal, and colorful gemstones. It communicates with other Clinkles by gently tapping its crystal feet against nearby rocks, producing delicate musical sounds. Some legends claim that groups of Clinkles can create beautiful underground melodies that echo through entire mountain ranges. Although Clinkle is usually peaceful, it can defend itself by releasing sharp bursts of crystalline energy. Fun fact: Clinkle occasionally mistakes its own reflection for another creature and spends hours trying to make friends with it!", "moves": [{"name": "Shard Flick", "type": "Crystal", "dmg": 20, "effect": "20% chance to deal 20% bonus damage"}, {"name": "Prism Blink", "type": "Crystal", "dmg": 18, "effect": "20% chance to reduce the next incoming attack's damage by 15%"}], "ability": {"name": "Crystal Clarity", "text": "Clinkle's crystal body becomes harder whenever it senses danger. Passive: the first time Clinkle falls below 50% HP, its facets harden, reducing damage from the next incoming attack by 20%."}, "role": "Defensive attacker / damage reduction"}, {"id": 469, "name": "Geodorb", "title": "The Rolling Geode", "rarity": "Rare", "types": ["Rock", "Crystal"], "weak": ["Water", "Nature", "Steel", "Earth"], "fam": "R-28", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Geode Roll", "atkType": "Rock", "alt": {"name": "Crystal Chime", "type": "Crystal", "mult": 0.9}, "ux": {"main": {"fx": "bonus", "ch": 0.2, "pct": 0.2}, "alt": {"fx": "shield", "ch": 0.2, "pct": 0.15}, "pass": {"fx": "halfShield", "pct": 0.25, "name": "Gemstone Guard"}}, "hp": 46, "df": 19, "dmg": 14, "ghp": 3.7, "gdf": 1.6, "gdmg": 1.3, "img": "assets/planet/alien-caves-360.webp", "event": "planet", "planet": "caves", "tier": "r", "lore": "Deep within rocky valleys and glittering underground caverns lives a cheerful little creature known as Geodorb. Its body resembles a perfectly round stone, but a cluster of beautiful gemstones growing from its back reveals the magical crystal energy hidden inside. Researchers believe Geodorb forms when a naturally occurring geode absorbs enough magical energy to awaken. Although Geodorb has tiny feet, it prefers traveling by rolling across the ground. Its round body allows it to move surprisingly quickly, especially when traveling downhill. The colorful crystals growing from its back produce delicate musical tones whenever Geodorb moves. These sounds help Geodorbs communicate with one another across enormous underground caverns. Despite its rocky exterior, Geodorb is extremely friendly and enjoys following travelers through caves and mountain paths. It is particularly fond of shiny objects and sometimes collects small gemstones to decorate its favorite resting places. Some legends claim that when a large group of Geodorbs rolls through a mountain valley, their crystals produce a beautiful melody that can be heard for miles. Fun fact: Geodorb loves rolling downhill but sometimes forgets that it has to climb back up afterward!", "moves": [{"name": "Geode Roll", "type": "Rock", "dmg": 21, "effect": "20% chance to deal 20% bonus damage"}, {"name": "Crystal Chime", "type": "Crystal", "dmg": 19, "effect": "20% chance to reduce the next incoming attack's damage by 15%"}], "ability": {"name": "Gemstone Guard", "text": "Geodorb's crystals become stronger whenever it is threatened. Passive: the first time Geodorb falls below 50% HP, its geode shell hardens, reducing damage from the next incoming attack by 25%."}, "role": "Defensive tank / rolling attacker"}, {"id": 470, "name": "Prismoth", "title": "The Rainbow Weaver", "rarity": "Super Rare", "types": ["Crystal", "Air"], "weak": ["Steel", "Earth", "Electric", "Ice", "Rock"], "fam": "S-40", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Prism Flutter", "atkType": "Crystal", "alt": {"name": "Rainbow Gust", "type": "Air", "mult": 0.88}, "ux": {"main": {"fx": "bonus", "ch": 0.2, "pct": 0.25}, "alt": {"fx": "daze", "ch": 0.2, "pct": 0.2}, "pass": {"fx": "halfShield", "pct": 0.25, "name": "Refracted Light"}}, "hp": 76, "df": 27, "dmg": 30, "ghp": 5, "gdf": 2, "gdmg": 2, "img": "assets/planet/alien-caves-s-360.webp", "event": "planet", "planet": "caves", "tier": "s", "lore": "High among the crystal-covered mountains and floating islands of the world lives an extraordinary creature known as Prismoth. Unlike ordinary moths, Prismoth possesses enormous wings made from hundreds of transparent crystal facets. Whenever sunlight passes through these magnificent wings, brilliant rainbows scatter across the surrounding landscape. Researchers believe Prismoth's wings naturally absorb light and separate it into different colors, allowing the creature to create beautiful displays even on cloudy days. Despite its delicate appearance, Prismoth's crystal wings are surprisingly strong and can withstand powerful winds. Prismoth is gentle and peaceful, preferring to spend its days floating among clouds and basking in warm sunlight. It is especially fond of colorful flowers and sparkling gemstones. Some legends claim that the first rainbow appeared when a Prismoth spread its wings after a great storm. Travelers consider spotting a Prismoth to be a sign of good fortune, particularly when its wings create a complete rainbow across the sky. Although Prismoth rarely fights, it can defend itself by releasing dazzling bursts of refracted light and powerful gusts of wind. Fun fact: Prismoth loves chasing rainbows, but it sometimes forgets that it created them itself!", "moves": [{"name": "Prism Flutter", "type": "Crystal", "dmg": 32, "effect": "20% chance to deal 25% bonus damage"}, {"name": "Rainbow Gust", "type": "Air", "dmg": 28, "effect": "20% chance to reduce the enemy's next attack damage by 20%"}], "ability": {"name": "Refracted Light", "text": "Prismoth's crystal wings can scatter incoming energy, making it difficult for opponents to land a powerful attack. Passive: the first time Prismoth falls below 50% HP, its wings flash brilliantly, reducing damage from the next incoming attack by 25%."}, "role": "Magical attacker / evasive support"}, {"id": 471, "name": "Snowbloop", "title": "The Bouncing Snowball", "rarity": "Common", "types": ["Ice"], "weak": ["Fire", "Steel"], "fam": "C-54", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Bloop Bounce", "atkType": "Ice", "alt": {"name": "Frosty Splatter", "type": "Ice", "mult": 0.87}, "ux": {"main": {"fx": "bonus", "ch": 0.2, "pct": 0.2}, "alt": {"fx": "atkdown", "ch": 0.25, "pct": 0.15}, "pass": {"fx": "halfShield", "pct": 0.3, "name": "Squishy Shield"}}, "hp": 88, "df": 32, "dmg": 24, "ghp": 5, "gdf": 2, "gdmg": 2, "img": "assets/planet/alien-ice-c-360.webp", "event": "planet", "planet": "ice", "tier": "c", "lore": "High in the frozen mountains, where snow never melts and icy winds sweep across the valleys, lives an extraordinary creature known as Snowbloop. Although it resembles an ordinary snowball, Snowbloop is actually made from a mysterious gelatinous substance that remains permanently frozen without becoming solid. Its round body is incredibly elastic, allowing it to stretch, squash, and bounce without breaking apart. Deep inside Snowbloop floats a glowing snowflake crystal that produces a constant supply of magical frost. Researchers believe this crystal is responsible for Snowbloop's unusual body and remarkable resistance to physical impacts. Snowbloop is extremely playful and spends much of its time bouncing down snowy hillsides, leaping between frozen rocks, and surprising unsuspecting travelers. Despite its icy appearance, Snowbloop is surprisingly comfortable to cuddle. Its outer surface feels like cool, fluffy snow rather than hard ice. Some legends claim that Snowbloops are born when a perfectly formed snowflake lands inside a pool of enchanted winter water. Although Snowbloop rarely seeks out battles, its powerful bouncing attacks and elastic body make it a surprisingly difficult opponent. Fun fact: Snowbloop loves being thrown like a snowball, but it usually bounces right back into the thrower's arms!", "moves": [{"name": "Bloop Bounce", "type": "Ice", "dmg": 30, "effect": "20% chance to deal 20% bonus damage"}, {"name": "Frosty Splatter", "type": "Ice", "dmg": 26, "effect": "25% chance to reduce enemy Attack by 15%"}], "ability": {"name": "Squishy Shield", "text": "Snowbloop's gelatinous body absorbs the force of incoming attacks. Passive: the first time Snowbloop falls below 50% HP, its body becomes extra squishy, reducing damage from the next incoming attack by 30%."}, "role": "Defensive tank / bouncing counterattacker"}, {"id": 472, "name": "Frostnik", "title": "The Frosty Figure Skater", "rarity": "Rare", "types": ["Ice", "Water"], "weak": ["Fire", "Steel", "Electric", "Nature"], "fam": "R-29", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Frosty Twirl", "atkType": "Ice", "alt": {"name": "Skating Splash", "type": "Water", "mult": 0.92}, "ux": {"main": {"fx": "evade", "ch": 0.2}, "alt": {"fx": "defdown", "ch": 0.2, "pct": 0.15}, "pass": {"fx": "halfShield", "pct": 0.2, "name": "Perfect Landing"}}, "hp": 55, "df": 18, "dmg": 21, "ghp": 4, "gdf": 1.5, "gdmg": 1.7, "img": "assets/planet/alien-ice-360.webp", "event": "planet", "planet": "ice", "tier": "r", "lore": "Frostnik is a cheerful little creature found on frozen lakes and snowy mountain ponds. Its incredibly fluffy body keeps it warm even during the coldest winter storms. Although its tiny feet appear too small for skating, Frostnik possesses an extraordinary sense of balance. It can perform complicated spins, jumps, and turns without ever losing its footing. Its magical skates freeze water beneath their blades, allowing Frostnik to glide across lakes that haven't frozen yet. Frostnik loves performing for other creatures and becomes especially excited when someone applauds its tricks. Groups of Frostnik sometimes gather to perform elaborate skating routines beneath the northern lights. Fun fact: Frostnik occasionally gets so dizzy from spinning that it forgets which direction it was originally skating!", "moves": [{"name": "Frosty Twirl", "type": "Ice", "dmg": 24, "effect": "20% chance to dodge the next attack"}, {"name": "Skating Splash", "type": "Water", "dmg": 22, "effect": "20% chance to reduce enemy Defense by 15%"}], "ability": {"name": "Perfect Landing", "text": "The first time Frostnik falls below 50% HP, it performs a dazzling spin, reducing damage from the next incoming attack by 20%."}, "role": "Agile attacker / evasive skater"}, {"id": 473, "name": "Auroraquin", "title": "The Northern Lights Penguin", "rarity": "Super Rare", "types": ["Ice", "Light"], "weak": ["Fire", "Steel", "Dark", "Ghost"], "fam": "S-41", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Aurora Flurry", "atkType": "Ice", "alt": {"name": "Polar Radiance", "type": "Light", "mult": 0.94}, "ux": {"main": {"fx": "atkdown", "ch": 0.2, "pct": 0.15}, "alt": {"fx": "heal", "ch": 0.2, "pct": 0.1}, "pass": {"fx": "halfShield", "pct": 0.25, "name": "Northern Glow"}}, "hp": 82, "df": 30, "dmg": 29, "ghp": 5, "gdf": 2, "gdmg": 2, "img": "assets/planet/alien-ice-s-360.webp", "event": "planet", "planet": "ice", "tier": "s", "lore": "Far beyond the frozen mountains, where the night sky shimmers with brilliant curtains of color, lives an extraordinary creature known as Auroraquin. Its magnificent feathers absorb the magical light of the aurora borealis, allowing it to create beautiful displays of color even during the darkest polar nights. Although Auroraquin cannot fly, it can spread its luminous flippers and glide effortlessly across frozen landscapes, leaving sparkling trails of light behind it. Auroraquin is gentle and protective, often guiding lost creatures through dangerous snowstorms with the glow of its feathers. Researchers believe Auroraquin's feathers can store sunlight during the day and release it as magical aurora energy at night. Some legends claim that when several Auroraquins gather beneath a clear winter sky, their synchronized displays can create entirely new northern lights. Fun fact: Auroraquin loves sliding on its belly across frozen lakes, but sometimes gets so distracted by its own colorful reflection that it forgets to stop!", "moves": [{"name": "Aurora Flurry", "type": "Ice", "dmg": 32, "effect": "20% chance to reduce enemy Attack by 15%"}, {"name": "Polar Radiance", "type": "Light", "dmg": 30, "effect": "20% chance to restore 10% maximum HP"}], "ability": {"name": "Northern Glow", "text": "The first time Auroraquin falls below 50% HP, its feathers shine brilliantly, reducing damage from the next incoming attack by 25%."}, "role": "Magical attacker / defensive support"}, {"id": 474, "name": "Sizzlit", "title": "The Hopping Ember", "rarity": "Common", "types": ["Fire", "Electric"], "weak": ["Water", "Earth", "Rock"], "fam": "C-55", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Ember Hop", "atkType": "Fire", "alt": {"name": "Spark Pop", "type": "Electric", "mult": 0.91}, "ux": {"main": {"fx": "bonus", "ch": 0.2, "pct": 0.2}, "alt": {"fx": "defdown", "ch": 0.2, "pct": 0.15}, "pass": {"fx": "halfBoost", "pct": 0.2, "name": "Overcharged Bounce"}}, "hp": 40, "df": 12, "dmg": 19, "ghp": 3.2, "gdf": 1.1, "gdmg": 1.8, "img": "assets/planet/alien-lava-c-360.webp", "event": "planet", "planet": "lava", "tier": "c", "lore": "Sizzlit is a tiny, energetic creature born when a magical ember is struck by lightning during a powerful thunderstorm. Its little body constantly flickers with warm orange flames and bright yellow electrical sparks. Although Sizzlit has tiny legs, it can jump extraordinary distances by releasing bursts of energy beneath its feet. Sizzlit is playful, curious, and incredibly energetic. It rarely stays still for more than a few seconds, preferring to bounce between rocks, race through open fields, and chase falling sparks. Researchers have discovered that Sizzlit's body becomes brighter whenever it is excited. Groups of Sizzlits sometimes gather during thunderstorms, creating spectacular displays of dancing fire and electricity. Despite its fiery appearance, Sizzlit can control its temperature and is surprisingly comfortable to hold. Fun fact: Sizzlit sometimes becomes so excited that it accidentally jumps straight into the air and forgets where it was trying to go!", "moves": [{"name": "Ember Hop", "type": "Fire", "dmg": 23, "effect": "20% chance to deal 20% bonus damage"}, {"name": "Spark Pop", "type": "Electric", "dmg": 21, "effect": "20% chance to reduce enemy Defense by 15%"}], "ability": {"name": "Overcharged Bounce", "text": "The first time Sizzlit falls below 50% HP, its next attack deals 20% additional damage."}, "role": "Fast attacker / critical-hit specialist"}, {"id": 475, "name": "Magmallow", "title": "The Toasted Marshmallow Alien", "rarity": "Rare", "types": ["Fire", "Earth"], "weak": ["Water", "Nature", "Air"], "fam": "R-30", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Toasted Burst", "atkType": "Fire", "alt": {"name": "Molten Hop", "type": "Earth", "mult": 0.93}, "ux": {"main": {"fx": "burn", "ch": 0.2, "turns": 2}, "alt": {"fx": "defup", "ch": 0.2, "pct": 0.15, "turns": 2}, "pass": {"fx": "halfHealDef", "pct": 0.15, "def": 0.15, "turns": 2, "name": "Campfire Core"}}, "hp": 68, "df": 23, "dmg": 25, "ghp": 4.7, "gdf": 1.9, "gdmg": 2.1, "img": "assets/planet/alien-lava-360.webp", "event": "planet", "planet": "lava", "tier": "r", "lore": "Deep beneath volcanic mountains, where glowing magma flows through ancient stone tunnels, lives an unusual creature known as Magmallow. Its soft, squishy body resembles a perfectly toasted marshmallow, but its warm exterior hides a powerful core of molten energy. Researchers believe Magmallow forms when magical volcanic minerals absorb enough heat to become living creatures. Despite its fiery origins, Magmallow is friendly and affectionate. It enjoys resting beside campfires, collecting warm stones, and helping other creatures stay comfortable during cold nights. Its marshmallow-like body can stretch and compress without injury, while its volcanic-rock feet protect it from the intense heat of molten lava. When Magmallow becomes excited, its toasted patches darken and tiny flames flicker from its head. Some travelers believe that encountering a Magmallow near a campfire brings good fortune and guarantees a warm night's sleep. Fun fact: Magmallow loves roasting marshmallows, but sometimes accidentally tries to roast its own stretchy arms!", "moves": [{"name": "Toasted Burst", "type": "Fire", "dmg": 28, "effect": "20% chance to inflict Burn for 2 turns"}, {"name": "Molten Hop", "type": "Earth", "dmg": 26, "effect": "20% chance to increase own Defense by 15% for 2 turns"}], "ability": {"name": "Campfire Core", "text": "The first time Magmallow falls below 50% HP, its magma core heats up, restoring 15% of its maximum HP and increasing its Defense by 15% for 2 turns."}, "role": "Balanced attacker / resilient brawler"}, {"id": 476, "name": "Volcanoodle", "title": "The Wiggly Lava Dragon", "rarity": "Super Rare", "types": ["Dragon", "Fire"], "weak": ["Water", "Earth", "Ice", "Crystal", "Arcane"], "fam": "S-42", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Lava Lash", "atkType": "Fire", "alt": {"name": "Draconic Coil", "type": "Dragon", "mult": 0.94}, "ux": {"main": {"fx": "burn", "ch": 0.25, "turns": 2}, "alt": {"fx": "defdown", "ch": 0.25, "pct": 0.2, "turns": 2}, "pass": {"fx": "halfBoost", "pct": 0.25, "bt": ["Fire"], "n": 3, "name": "Magma Flow"}}, "hp": 86, "df": 29, "dmg": 32, "ghp": 5.5, "gdf": 2.1, "gdmg": 2.5, "img": "assets/planet/alien-lava-s-360.webp", "event": "planet", "planet": "lava", "tier": "s", "lore": "Deep within volcanic mountains, where rivers of molten lava flow through winding tunnels, lives a playful little dragon known as Volcanoodle. Unlike most dragons, Volcanoodle possesses an incredibly long and flexible body that allows it to twist, stretch, and squeeze through even the narrowest cracks in volcanic rock. Its glowing scales absorb heat from the surrounding lava, keeping its body warm and full of energy. Despite its fiery appearance, Volcanoodle is friendly and curious. It enjoys exploring underground tunnels, collecting unusual stones, and surprising other creatures by popping out of unexpected places. Researchers have observed Volcanoodle swimming through molten lava as effortlessly as a fish moves through water. Some legends claim that the winding lava tunnels beneath ancient volcanoes were created by generations of Volcanoodles playfully burrowing through the mountains. Fun fact: Volcanoodle sometimes curls itself into a perfect spiral and falls asleep floating on the surface of a lava pool!", "moves": [{"name": "Lava Lash", "type": "Fire", "dmg": 36, "effect": "25% chance to inflict Burn for 2 turns"}, {"name": "Draconic Coil", "type": "Dragon", "dmg": 34, "effect": "25% chance to reduce enemy Defense by 20% for 2 turns"}], "ability": {"name": "Magma Flow", "text": "Volcanoodle's molten scales become more powerful when it is in danger. Passive: the first time Volcanoodle falls below 50% HP, its Fire-type attacks deal 25% additional damage for 3 turns. Its glowing magma cracks become brighter while the ability is active."}, "role": "Powerful attacker / resilient brawler"}, {"id": 477, "name": "Starbloop", "title": "The Little Wishing Star", "rarity": "Common", "types": ["Light"], "weak": ["Dark", "Ghost"], "fam": "C-56", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Twinkle Beam", "atkType": "Light", "alt": {"name": "Starlit Support", "type": "Light", "mult": 0, "heal": 0.15}, "ux": {"main": {"fx": "blind", "ch": 0.2, "pct": 0.15, "turns": 2}, "alt": null, "pass": {"fx": "enterAcc", "ch": 0.2, "pct": 0.1, "turns": 2, "name": "Radiant Cheer"}}, "hp": 38, "df": 12, "dmg": 18, "ghp": 2.8, "gdf": 1, "gdmg": 1.6, "img": "assets/planet/alien-nebula-c-360.webp", "event": "planet", "planet": "nebula", "tier": "c", "lore": "High above the clouds, where the night sky glitters with countless stars, lives a cheerful little creature known as Starbloop. Researchers believe Starbloop is born when concentrated starlight gathers enough magical energy to become a living creature. Its soft golden body produces a warm, comforting glow that becomes brighter whenever it feels happy. Starbloop is naturally curious and affectionate. It loves following travelers, exploring unfamiliar places, and making new friends. Although it cannot speak, Starbloop communicates by changing the brightness and rhythm of its glow. Groups of Starbloops sometimes gather high above the clouds, arranging themselves into beautiful patterns that resemble constellations. Ancient legends claim that seeing a Starbloop streak across the night sky means a wish will soon come true. Fun fact: Starbloop sometimes tries to imitate real constellations, but it often gets distracted and accidentally makes silly shapes instead!", "moves": [{"name": "Twinkle Beam", "type": "Light", "dmg": 22, "effect": "20% chance to reduce enemy Accuracy by 15% for 2 turns"}, {"name": "Starlit Support", "type": "Light", "dmg": 0, "effect": "Restores 15% of its own maximum HP"}], "ability": {"name": "Radiant Cheer", "text": "When Starbloop enters battle, it has a 20% chance to increase its team's Accuracy by 10% for 2 turns."}, "role": "Support attacker / lightweight"}, {"id": 478, "name": "Nebuloo", "title": "The Stardust Cloud", "rarity": "Rare", "types": ["Air", "Arcane"], "weak": ["Electric", "Ice", "Rock", "Dark", "Steel"], "fam": "R-31", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Rainbow Whirlwind", "atkType": "Air", "alt": {"name": "Nebula Burst", "type": "Arcane", "mult": 1.13}, "ux": {"main": {"fx": "daze", "ch": 0.25, "pct": 0.2}, "alt": {"fx": "bonus", "ch": 0.2, "pct": 0.25}, "pass": {"fx": "halfShield", "pct": 0.25, "name": "Stardust Veil"}}, "hp": 66, "df": 23, "dmg": 29, "ghp": 4.5, "gdf": 1.7, "gdmg": 2.2, "img": "assets/planet/alien-nebula-360.webp", "event": "planet", "planet": "nebula", "tier": "r", "lore": "High above the tallest mountains, where colorful clouds drift among the stars, lives an extraordinary creature known as Nebuloo. Unlike ordinary clouds, Nebuloo is formed from magical mist infused with tiny particles of celestial stardust. Its fluffy body constantly shifts between beautiful shades of pink, purple, turquoise, and gold. Researchers believe Nebuloo is born when powerful winds carry enchanted stardust into the upper atmosphere, allowing the particles to gather into a living cloud. Nebuloo is cheerful, curious, and extremely affectionate. It enjoys floating alongside travelers, creating miniature rainbows, and surprising other creatures with gentle showers of sparkling stardust. Although its body appears soft and delicate, Nebuloo can control powerful air currents and release concentrated bursts of magical energy when threatened. Its colorful cloud tendrils allow it to sense changes in the wind, making Nebuloo particularly skilled at predicting approaching storms. Some legends claim that when several Nebuloos gather beneath a clear night sky, their combined magic creates beautiful rainbow-colored clouds that shimmer like distant galaxies. Because Nebuloo spends much of its time high above the clouds, sightings are uncommon, and many travelers consider encountering one a sign of good fortune. Fun fact: Nebuloo loves making cloud shapes to entertain other creatures, but sometimes accidentally turns itself into the shape of a giant fluffy chicken!", "moves": [{"name": "Rainbow Whirlwind", "type": "Air", "dmg": 30, "effect": "25% chance to reduce the enemy's next attack damage by 20%"}, {"name": "Nebula Burst", "type": "Arcane", "dmg": 34, "effect": "20% chance to deal 25% additional damage"}], "ability": {"name": "Stardust Veil", "text": "Nebuloo's magical cloud body becomes difficult to strike when threatened. Passive: the first time Nebuloo falls below 50% HP, it surrounds itself with a swirling veil of stardust, reducing damage from the next incoming attack by 25%."}, "role": "Magical attacker / evasive support"}, {"id": 479, "name": "Cometail", "title": "The Celestial Fox", "rarity": "Super Rare", "types": ["Light", "Air"], "weak": ["Dark", "Ghost", "Electric", "Ice", "Rock"], "fam": "S-43", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Comet Crash", "atkType": "Light", "alt": {"name": "Stardust Sprint", "type": "Air", "mult": 0.84}, "ux": {"main": {"fx": "bonus", "ch": 0.25, "pct": 0.2}, "alt": {"fx": "evade", "ch": 0.25}, "pass": {"fx": "halfBoost", "pct": 0.2, "n": 2, "name": "Cosmic Momentum"}}, "hp": 79, "df": 26, "dmg": 34, "ghp": 5, "gdf": 2, "gdmg": 2.4, "img": "assets/planet/alien-nebula-s-360.webp", "event": "planet", "planet": "nebula", "tier": "s", "lore": "High above the clouds, where the stars shimmer against the endless night sky, lives a mysterious creature known as Cometail. Its beautiful midnight-blue fur contains tiny glowing markings that resemble distant constellations, while its magnificent tail trails brilliant streams of golden and rainbow-colored starlight. Researchers believe Cometail was born from the magical energy left behind by a passing comet. Unlike ordinary foxes, Cometail can run effortlessly through the air, using powerful currents of wind and celestial energy to propel itself across enormous distances. Its glowing tail becomes brighter as it accelerates, sometimes making Cometail appear indistinguishable from a shooting star. Despite its extraordinary speed and magical abilities, Cometail is playful, affectionate, and extremely curious. It loves racing through the clouds, chasing falling stars, and surprising other creatures with spectacular aerial displays. Ancient legends claim that when a Cometail streaks across the night sky, anyone who witnesses its brilliant trail will experience a moment of unexpected good fortune. Because Cometail rarely descends from the upper atmosphere, encountering one is considered an extraordinary event. Fun fact: Cometail sometimes chases its own comet tail, accidentally creating beautiful spirals of starlight in the sky!", "moves": [{"name": "Comet Crash", "type": "Light", "dmg": 38, "effect": "25% chance to deal 20% additional damage"}, {"name": "Stardust Sprint", "type": "Air", "dmg": 32, "effect": "25% chance to dodge the next incoming attack"}], "ability": {"name": "Cosmic Momentum", "text": "Cometail becomes faster and more powerful as its celestial energy builds. Passive: the first time Cometail falls below 50% HP, its comet tail shines brilliantly, increasing the damage of its next two attacks by 20%."}, "role": "High-damage magical attacker / evasive striker"}, {"id": 480, "name": "Gloomby", "title": "The Shy Shadow Puff", "rarity": "Common", "types": ["Dark"], "weak": ["Light", "Nature"], "fam": "C-57", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Shadow Pounce", "atkType": "Dark", "alt": {"name": "Gloom Puff", "type": "Dark", "mult": 0.83}, "ux": {"main": {"fx": "bonus", "ch": 0.2, "pct": 0.2}, "alt": {"fx": "daze", "ch": 0.25, "pct": 0.15}, "pass": {"fx": "halfShield", "pct": 0.25, "name": "Shadow Snuggle"}}, "hp": 43, "df": 15, "dmg": 18, "ghp": 3.3, "gdf": 1.2, "gdmg": 1.6, "img": "assets/planet/alien-shadow-c-360.webp", "event": "planet", "planet": "shadow", "tier": "c", "lore": "Deep within moonlit forests and quiet caves lives a mysterious little creature known as Gloomby. Its round body is covered in incredibly soft, midnight-black fur that seems to absorb the light around it. Only its enormous glowing violet eyes are easily visible in complete darkness. Researchers believe Gloomby forms when magical shadows gather together in places where moonlight rarely reaches. Although Gloomby looks mysterious, it is one of the gentlest Dark-type creatures. It is extremely shy and often hides behind rocks, trees, or larger creatures when frightened. Its fluffy body can flatten into a nearly invisible shadow, allowing it to escape danger or sneak into tiny hiding places. Gloomby is especially affectionate toward creatures and people it trusts. Once it becomes comfortable, it enjoys curling up in laps and making a quiet, rumbling purr. Groups of Gloomby sometimes gather beneath the stars, their glowing eyes resembling tiny constellations scattered across the forest floor. Ancient stories claim that Gloomby quietly watches over sleeping travelers, keeping nightmares away by surrounding them with comforting shadows. Fun fact: Gloomby loves playing hide-and-seek, but its enormous glowing eyes usually give away its hiding spot!", "moves": [{"name": "Shadow Pounce", "type": "Dark", "dmg": 23, "effect": "20% chance to deal 20% bonus damage"}, {"name": "Gloom Puff", "type": "Dark", "dmg": 19, "effect": "25% chance to reduce the enemy's next attack damage by 15%"}], "ability": {"name": "Shadow Snuggle", "text": "The first time Gloomby falls below 50% HP, it wraps itself in protective darkness, reducing damage from the next incoming attack by 25%."}, "role": "Evasive attacker / enemy weakening"}, {"id": 481, "name": "Lanternook", "title": "The Timid Lanternkeeper", "rarity": "Rare", "types": ["Ghost", "Light"], "weak": ["Light", "Arcane", "Dark"], "fam": "R-32", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Phantom Flicker", "atkType": "Ghost", "alt": {"name": "Guiding Glow", "type": "Light", "mult": 0.9}, "ux": {"main": {"fx": "daze", "ch": 0.25, "pct": 0.2}, "alt": {"fx": "heal", "ch": 0.25, "pct": 0.1}, "pass": {"fx": "halfShield", "pct": 0.3, "name": "Lantern's Refuge"}}, "hp": 68, "df": 28, "dmg": 26, "ghp": 4.6, "gdf": 2, "gdmg": 2, "img": "assets/planet/alien-shadow-360.webp", "event": "planet", "planet": "shadow", "tier": "r", "lore": "Deep within misty forests and abandoned ruins lives a mysterious little creature known as Lanternook. Its translucent body glows with faint lavender light, while its enormous eyes allow it to see wandering spirits that remain invisible to most creatures. Although Lanternook resembles a ghost, researchers believe it originated from a distant world where living creatures communicate through magical light. Lanternook carries a tiny enchanted lantern containing a golden flame that never burns out. This flame reacts to the emotions of nearby creatures, shining brighter whenever someone feels frightened or lost. Despite its supernatural abilities, Lanternook is incredibly shy. It often hides behind its lantern when approached and prefers observing strangers from a safe distance. However, Lanternook possesses a deeply compassionate nature. When it encounters a lost traveler, it quietly emerges from the shadows and guides them toward safety with its gentle golden glow. Ancient legends claim that the mysterious lights sometimes seen floating through dark forests are actually groups of Lanternooks helping wandering spirits find their way home. Because Lanternook rarely reveals itself to anyone who isn't lost, sightings are considered exceptionally fortunate. Fun fact: Lanternook is afraid of the dark! Even though it is a Ghost-type creature, it refuses to sleep unless its lantern is glowing beside it.", "moves": [{"name": "Phantom Flicker", "type": "Ghost", "dmg": 29, "effect": "25% chance to reduce the enemy's next attack damage by 20%"}, {"name": "Guiding Glow", "type": "Light", "dmg": 26, "effect": "25% chance to restore 10% of Lanternook's maximum HP"}], "ability": {"name": "Lantern's Refuge", "text": "When Lanternook is frightened, its enchanted lantern releases a protective golden glow. Passive: the first time Lanternook falls below 50% HP, its lantern creates a magical barrier that reduces damage from the next incoming attack by 30%."}, "role": "Defensive magical attacker / protective support"}, {"id": 482, "name": "Eclipsa", "title": "The Moonshadow Cat", "rarity": "Super Rare", "types": ["Dark", "Arcane"], "weak": ["Light", "Nature", "Steel"], "fam": "S-44", "stage": 1, "stages": 1, "evolvesAt": null, "attack": "Eclipse Claw", "atkType": "Dark", "alt": {"name": "Lunar Hex", "type": "Arcane", "mult": 0.9}, "ux": {"main": {"fx": "bonus", "ch": 0.25, "pct": 0.2}, "alt": {"fx": "defdown", "ch": 0.25, "pct": 0.2, "turns": 2}, "pass": {"fx": "halfShield", "pct": 0.3, "name": "Eclipse Veil"}}, "hp": 77, "df": 29, "dmg": 35, "ghp": 5, "gdf": 2, "gdmg": 2.5, "img": "assets/planet/alien-shadow-s-360.webp", "event": "planet", "planet": "shadow", "tier": "s", "lore": "High among ancient observatories and moonlit mountain peaks lives a mysterious creature known as Eclipsa. Its magnificent midnight-black fur contains thousands of tiny glowing stars that shift and shimmer like the night sky. Researchers believe these markings change to reflect the positions of distant constellations. Eclipsa possesses an unusual connection to the moon. Its crescent-shaped tail absorbs lunar energy, allowing it to manipulate shadows and release powerful bursts of arcane magic. Although Eclipsa appears mysterious and sometimes intimidating, it is actually a curious and affectionate creature. It enjoys watching the stars, sleeping beneath moonlight, and quietly following travelers who explore at night. During a lunar eclipse, Eclipsa's fur becomes almost completely black while its eyes and celestial markings shine with brilliant silver light. Ancient legends claim that Eclipsa can briefly step between shadows, disappearing from one place and reappearing somewhere else beneath the same moonlight. Because Eclipsa rarely appears during daylight, many people believe it exists only in stories told by astronomers and nighttime travelers. Some researchers have even suggested that the stars in Eclipsa's fur reveal constellations that have not yet been discovered. Fun fact: Eclipsa loves chasing moonlight reflected on the ground, but becomes terribly confused when the reflection disappears behind a cloud!", "moves": [{"name": "Eclipse Claw", "type": "Dark", "dmg": 39, "effect": "25% chance to deal 20% bonus damage"}, {"name": "Lunar Hex", "type": "Arcane", "dmg": 35, "effect": "25% chance to reduce enemy Defense by 20% for 2 turns"}], "ability": {"name": "Eclipse Veil", "text": "When Eclipsa is threatened, its fur darkens and a glowing ring of moonlight surrounds its body. Passive: the first time Eclipsa falls below 50% HP, it becomes partially intangible, reducing damage from the next incoming attack by 30%."}, "role": "Magical attacker / evasive trickster"}];
